const src = $json.body && $json.body.message !== undefined ? $json.body : $json;
const user_message    = (src.message    || '').trim();
const conversation_id =  src.conversation_id || 'default';
const history         = Array.isArray(src.history) ? src.history : [];
return [{ json: { user_message, conversation_id, history } }];

// Parse registry
const registryRaw = $input.first().json.data || '[]';
let registry = [];
try { registry = JSON.parse(registryRaw); } catch(e) { registry = []; }

// Get user message from Extract Fields
const upstream = $('Extract Fields').first().json;
const msg = (upstream.user_message || '').toLowerCase();

// Try to match user message to a project
let matched = null;
for (const p of registry) {
  const slugWords = p.slug.replace(/-/g, ' ');
  const titleWords = (p.title || '').toLowerCase();
  // Check if any significant word from slug/title appears in message
  const keywords = slugWords.split(' ').concat(titleWords.split(' '))
    .filter(w => w.length > 3);
  if (keywords.some(k => msg.includes(k))) {
    matched = p;
    break;
  }
}

// Check if user is asking for all/summary
const wantsAll = !matched && /all|summary|list|every|overview|which/.test(msg);

return [{
  json: {
    user_message:    upstream.user_message,
    history:         upstream.history,
    conversation_id: upstream.conversation_id,
    registry,
    matched_slug:    matched ? matched.slug : null,
    matched_title:   matched ? matched.title : null,
    wants_all:       wantsAll || !matched
  }
}];

const html = $input.first().json.data || '';
const upstream = $('Identify Project').first().json;

// RAG status
const ragMatch = html.match(/overall[\s\S]{0,80}?(green|amber|red)/i)
               || html.match(/rag[^>]*>[\s\S]{0,20}?(green|amber|red)/i);
const ragStatus = ragMatch ? ragMatch[1].toUpperCase() : 'Unknown';

// Overdue count
const overdueMatch = html.match(/(\d+)\s*(?:steps?\s*)?overdue/i);
const overdueCount = overdueMatch ? parseInt(overdueMatch[1]) : 0;

// Strip HTML tags
const stripTags = s => s.replace(/<[^>]+>/g, '').trim();

// Parse step rows
const steps = [];
const rowRe = /<tr[^>]*>([\s\S]*?)<\/tr>/gi;
let m;
while ((m = rowRe.exec(html)) !== null) {
  const cells = [...m[1].matchAll(/<td[^>]*>([\s\S]*?)<\/td>/gi)]
                  .map(c => stripTags(c[1]));
  if (cells.length >= 3 && /^\d+$/.test(cells[0])) {
    steps.push({
      step:        cells[0],
      description: cells[1] || '',
      dri:         cells[2] || '',
      status:      cells[3] || '',
      est_end:     cells[4] || '',
      actual:      cells[5] || ''
    });
  }
}

return [{
  json: {
    user_message:    upstream.user_message,
    history:         upstream.history,
    conversation_id: upstream.conversation_id,
    context_type:    'specific',
    project_context: JSON.stringify({
      project_name:  upstream.matched_title,
      slug:          upstream.matched_slug,
      rag_status:    ragStatus,
      overdue_count: overdueCount,
      total_steps:   steps.length,
      steps
    }, null, 2)
  }
}];

const upstream = $('Identify Project').first().json;
const registry = upstream.registry || [];

const summary = registry.map(p => ({
  project:   p.title,
  slug:      p.slug,
  progress:  p.progress + '%',
  done:      p.done + ' / ' + p.total + ' steps',
  objective: p.objective
}));

return [{
  json: {
    user_message:    upstream.user_message,
    history:         upstream.history,
    conversation_id: upstream.conversation_id,
    context_type:    'all',
    project_context: JSON.stringify({
      total_projects: registry.length,
      projects: summary
    }, null, 2)
  }
}];

const item = $input.first().json;
const history = Array.isArray(item.history) ? item.history : [];
const isAll = item.context_type === 'all';

const registry = $('Identify Project').first().json.registry || [];
const projectList = registry.map(p => '- ' + p.title + ' (slug: ' + p.slug + ')').join('\n');

const systemPrompt =
  `You are a project assistant for the AI PM Tool Multi Project Tracker.\n` +
  `Answer ONLY based on the project data provided below.\n` +
  `If information is not in the data, say "I don't have that information in the current tracker."\n` +
  `Never guess or fabricate step data or dates.\n` +
  `Keep answers concise unless the user asks for a full list.\n\n` +
  `Available projects:\n${projectList}\n\n` +
  `Project Data (today: ${new Date().toISOString().split('T')[0]}):\n` +
  item.project_context;

const messages = [
  ...history,
  { role: 'user', content: (item.user_message || '').trim() || 'Hello' }
];

return [{
  json: {
    conversation_id: item.conversation_id,
    project_context: item.project_context,
    request_body: {
      model:      'claude-sonnet-4-6',
      max_tokens: 400,
      system:     systemPrompt,
      messages
    }
  }
}];

const api = $input.first().json;
const reply =
  api.content && api.content[0] && api.content[0].text
    ? api.content[0].text
    : 'Sorry, I could not generate a response. Please try again.';
return [{
  json: {
    reply,
    sources:   ['projects/registry.json'],
    model:     api.model || 'claude-sonnet-4-6',
    timestamp: new Date().toISOString()
  }
}];
